transforms.code:
fields = ['toolingAssetId', 'assetName', 'parentId', 'assetTypeId', 'enabled', 'hasPositions', 'holdsInserts', 'scalesOutput', 'lifeUnit', 'lifetimeLimit', 'pmInterval', 'refurbInterval', 'refurbLimit', 'warnPct', 'calibrationIntervalDays', 'calibrationDue', 'setupMinutes', 'teardownMinutes']
info = dict((k, None) for k in fields)
info.update({'assetName': '', 'enabled': True, 'hasPositions': False, 'holdsInserts': False, 'scalesOutput': False})
if value is not None:
	rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.tooling.getTools({'toolingAssetId': value}) or [])
	if rows:
		for k in fields: info[k] = rows[0].get(k)
		info['toolingAssetId'] = value
return info

# Name and type are required
if not value['info'] or not (value['info']['assetName'] or '').strip() or value['info']['assetTypeId'] is None: return False
return dict(value['info']) != dict(value['orig'] or {})

security = value['security']
userCRUD = security['userCRUD'] if security else {}
canEdit = bool(userCRUD) and (userCRUD.get('isGatewayAdmin') or userCRUD.get('configureAssets', {}).get('enabled'))
return {'canCreate': canEdit, 'canUpdate': canEdit, 'canRead': True}

onChange.script:
# Scales output works from the positions
if origin == 'Browser' and not currentValue.value:
	self.view.custom.info.scalesOutput = False

# The limits are in the life unit; with none they don't count
if origin == 'Browser' and not currentValue.value:
	for k in ('lifetimeLimit', 'pmInterval', 'refurbInterval'):
		self.view.custom.info[k] = None

# A due date needs an interval: logging a calibration moves it on by the interval
if origin == 'Browser' and currentValue.value is None:
	self.view.custom.info.calibrationDue = None

config.script:
info = dict(self.view.custom.info)
# Settings that need another one are dropped without it
if not info.get('hasPositions'):
	info['scalesOutput'] = False
if not info.get('lifeUnit'):
	info['lifeUnit'] = None
	for k in ('lifetimeLimit', 'pmInterval', 'refurbInterval'):
		info[k] = None
if info.get('calibrationIntervalDays') is None:
	info['calibrationDue'] = None
userId = self.view.custom.security.userId
if info['toolingAssetId'] is None:
	toolingAssetId, msg = system.kanoa.tooling.addTool(info, userId)
else:
	toolingAssetId, msg = info['toolingAssetId'], system.kanoa.tooling.updateTool(info, userId)[1]
if msg:
	system.kanoa.toast.show({'type': 'error', 'message': msg})
	return
system.kanoa.toast.show({'type': 'success', 'message': 'Tool saved'})
system.perspective.sendMessage('toolUpdated', {'toolingAssetId': toolingAssetId})
self.view.refreshBinding('custom.info')
return
